 2 | pragma solidity 0.8.11;
 3 | 
 4 | /// votescrow extended with delegation
 5 | 
 6 | // import {Math} from '@openzeppelin-contracts/utils/math/SafeCast.sol';
 7 | 
 8 | import '@openzeppelin/contracts/access/Ownable.sol';
 9 | 
10 | import {VoteEscrowCore} from './VoteEscrowCore.sol';
11 | 
12 | interface IVoteEscrow {
13 |     function balanceOf(uint256) external view returns (uint256);
14 | 
15 |     function balanceOfAtNFT(uint256, uint256) external view returns (uint256);
16 | 
17 |     function ownerOf(uint256) external view returns (address);
18 | }
19 | 
20 | contract VoteEscrow is VoteEscrowCore, Ownable {
21 |     /**
22 |      * @dev Emitted when an account changes their delegate.
23 |      */
24 |     event DelegateChanged(uint256 indexed tokenId, uint256 indexed toTokenId, address indexed currentOwner);
25 | 
26 |     /**
27 |      * @dev Emitted when a token transfer or delegate change results in changes to a delegate's number of votes.
28 |      */
29 |     event DelegateVotesChanged(address indexed delegate, uint256 previousBalance, uint256 newBalance);
30 | 
31 |     /// @notice Delegate of the specific token
32 |     mapping(uint256 => uint256) public delegates;
33 | 
34 |     /// @notice Total delegated tokens to specific token
35 |     mapping(uint256 => uint256[]) public delegatedTokenIds;
36 | 
37 |     /// @notice A checkpoint for marking number of votes from a given block
38 |     struct Checkpoint {
39 |         uint256 fromBlock;
40 |         uint256[] delegatedTokenIds;
41 |     }
42 | 
43 |     /// @notice A record of votes checkpoints for each tokenId, by index
44 |     mapping(uint256 => mapping(uint256 => Checkpoint)) public checkpoints;
45 | 
46 |     /// @notice The number of checkpoints for each delegated tokenId
47 |     mapping(uint256 => uint256) public numCheckpoints;
48 | 
49 |     /// @notice minimum voting power required for delegation
50 |     uint256 public MIN_VOTING_POWER_REQUIRED = 0;
51 | 
52 |     constructor(address _token) {
53 |         token = _token;
54 |         voter = msg.sender;
55 |         point_history[0].blk = block.number;
56 |         point_history[0].ts = block.timestamp;
57 | 
58 |         supportedInterfaces[ERC165_INTERFACE_ID] = true;
59 |         supportedInterfaces[ERC721_INTERFACE_ID] = true;
60 |         supportedInterfaces[ERC721_METADATA_INTERFACE_ID] = true;
61 | 
62 |         // mint-ish
